import React, { useEffect, useMemo, useState } from 'react';
import './App.css';

export interface Line {
  id: number;
  text: string;
}

export type Language = 'en' | 'es';
export type Rate = 1 | 2;

/** Each transcript line plays for one second of audio; the clock ticks every 400 ms of real time. */
export const TICK_MS = 400;

const TRANSCRIPTS: Record<Language, Line[]> = {
  en: [
    { id: 1, text: 'Welcome to the dubbing review for episode four.' },
    { id: 2, text: 'The first voice sample mixes two speakers.' },
    { id: 3, text: 'Mark the lines where the timing drifts.' },
    { id: 4, text: 'The mix engineer joins after the break.' },
    { id: 5, text: 'Keep the pauses where the original pauses.' },
    { id: 6, text: 'Approve the take or request a new render.' },
    { id: 7, text: 'Export the approved mix to the project.' },
    { id: 8, text: 'Thanks, that is the end of the review.' }
  ],
  es: [
    { id: 1, text: 'Bienvenidos a la revisión del doblaje del episodio cuatro.' },
    { id: 2, text: 'La primera muestra de voz mezcla dos hablantes.' },
    { id: 3, text: 'Marquen las líneas donde el tiempo se desvía.' },
    { id: 4, text: 'El ingeniero de mezcla se une después de la pausa.' },
    { id: 5, text: 'Mantengan las pausas donde pausa el original.' },
    { id: 6, text: 'Aprueben la toma o pidan un nuevo render.' },
    { id: 7, text: 'Exporten la mezcla aprobada al proyecto.' },
    { id: 8, text: 'Gracias, ese es el final de la revisión.' }
  ]
};

// Fake transcript service. Treat it as given: the bugs are in App below.
// - Spanish answers slowly (700ms) and English quickly (150ms), so switching
//   there and back quickly produces responses that arrive out of order
export function loadTranscript(language: Language): Promise<Line[]> {
  const delay = language === 'es' ? 700 : 150;
  return new Promise((resolve) => {
    window.setTimeout(() => resolve(TRANSCRIPTS[language]), delay);
  });
}

export const LANGUAGE_NAMES: Record<Language, string> = { en: 'English', es: 'Spanish' };

export default function App() {
  const [language, setLanguage] = useState<Language>('en');
  const [lines, setLines] = useState<Line[]>([]);
  const [query, setQuery] = useState('');
  const [playing, setPlaying] = useState(false);
  const [rate, setRate] = useState<Rate>(1);
  const [position, setPosition] = useState(0);
  const total = lines.length;
  const finished = total > 0 && position >= total;

  useEffect(() => {
    let cancelled = false;
    setLines([]);
    loadTranscript(language).then((loaded) => {
      if (cancelled) return;
      setLines(loaded);
      setPosition(0);
    });
    return () => {
      cancelled = true;
    };
  }, [language]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return q ? lines.filter((line) => line.text.toLowerCase().includes(q)) : lines;
  }, [lines, query]);

  useEffect(() => {
    if (!playing) return;
    const timer = window.setInterval(() => {
      setPosition((current) => Math.min(current + rate, total));
    }, TICK_MS);
    return () => {
      window.clearInterval(timer);
    };
  }, [playing, rate, total]);

  useEffect(() => {
    if (finished) setPlaying(false);
  }, [finished]);

  const activeIndex = Math.min(position, total - 1);
  const active = lines[activeIndex];
  const status = total === 0
    ? `Loading ${LANGUAGE_NAMES[language]}…`
    : finished
      ? 'Finished'
      : `${LANGUAGE_NAMES[language]} transcript`;

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Dubbing Review Player (Solution)</h1>
          <p className="subtitle">The clock follows the rate, pause stops it, the search filters at once and the latest language wins.</p>
        </header>

        <div className="controls">
          <button type="button" className="play" onClick={() => setPlaying((value) => !value)}>
            {playing ? 'Pause' : 'Play'}
          </button>
          <button
            type="button"
            className={`rate rate-1x${rate === 1 ? ' rate--active' : ''}`}
            onClick={() => setRate(1)}
          >
            1×
          </button>
          <button
            type="button"
            className={`rate rate-2x${rate === 2 ? ' rate--active' : ''}`}
            onClick={() => setRate(2)}
          >
            2×
          </button>
          <span className="time">{position.toFixed(1)} s</span>
        </div>

        <div className="controls">
          <button type="button" className="lang lang-en" onClick={() => setLanguage('en')}>English</button>
          <button type="button" className="lang lang-es" onClick={() => setLanguage('es')}>Spanish</button>
          <span className="status">{status}</span>
        </div>

        <div className="field">
          <label className="label" htmlFor="transcript-search">Search the transcript</label>
          <input
            id="transcript-search"
            className="search"
            type="search"
            value={query}
            placeholder="Try mix, pause or render"
            onChange={(event: React.ChangeEvent<HTMLInputElement>) => setQuery(event.target.value)}
          />
        </div>

        {total > 0 && (
          <span className="position">Line {activeIndex + 1} of {total}</span>
        )}

        <ol className="lines">
          {filtered.map((line) => (
            <li key={line.id} className={`line${active && active.id === line.id ? ' line--active' : ''}`}>
              {line.text}
            </li>
          ))}
        </ol>
      </section>
    </main>
  );
}
